    public sealed class NoNetworkHandler : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken) => throw new HttpRequestException("Внешняя сеть отключена для автономной проверки"); }
    delegate bool EnumWindowCallback(nint hwnd,nint arg);
    [DllImport("user32.dll")] static extern bool EnumWindows(EnumWindowCallback callback,nint arg);
    [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern int GetWindowText(nint hwnd,System.Text.StringBuilder text,int max);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(nint hwnd,out uint pid);
    [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern int GetClassName(nint hwnd,System.Text.StringBuilder name,int max);
    [DllImport("user32.dll")] static extern bool EnumChildWindows(nint parent,EnumWindowCallback callback,nint arg);
    [DllImport("user32.dll")] static extern int GetDlgCtrlID(nint hwnd);
    [DllImport("user32.dll")] static extern nint SendMessage(nint hwnd,uint message,nint wParam,nint lParam);
    readonly List<object> results = [];
    public async Task<string> Eval(string code, int seconds=60)
    {
        await window.Web.ExecuteScriptAsync("window.__qa={done:false};(async()=>{"+code+"})().then(value=>window.__qa={done:true,value},error=>window.__qa={done:true,error:String(error?.stack||error)});");
        var timer=Stopwatch.StartNew();
        while(timer.Elapsed.TotalSeconds<seconds) {
            await Task.Delay(80);var raw=JsonSerializer.Deserialize<string>(await window.Web.ExecuteScriptAsync("JSON.stringify(window.__qa)"));using var doc=JsonDocument.Parse(raw??"{}");
            if(doc.RootElement.TryGetProperty("done",out var done)&&done.GetBoolean()) {if(doc.RootElement.TryGetProperty("error",out var error))throw new InvalidOperationException(error.GetString());return doc.RootElement.TryGetProperty("value",out var value)?value.GetRawText():"null";}
        }throw new TimeoutException("Desktop QA timed out: "+code[..Math.Min(200,code.Length)]);
    }
    async Task Check(string name,string code) {var timer=Stopwatch.StartNew();var value=await Eval(code);results.Add(new{name,ms=timer.ElapsedMilliseconds,value});await Report();}
    async Task Report()=>await File.WriteAllTextAsync(Path.Combine(window.Store.Root,"qa-results.json"),Json.Encode(results));
    async Task Shot(string name) {await Task.Delay(350);var folder=Path.Combine(window.Store.Root,"screenshots");Directory.CreateDirectory(folder);await using var file=File.Create(Path.Combine(folder,name+".png"));await window.Web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,file);}
    async Task Mouse(double x,double y,int clicks=1) {await window.Web.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",Json.Encode(new{type="mousePressed",x,y,button="left",clickCount=clicks}));await window.Web.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",Json.Encode(new{type="mouseReleased",x,y,button="left",clickCount=clicks}));await Task.Delay(350);}
    async Task Click(string selector) {var value=await Eval($"const b=document.querySelector({Json.Encode(selector)});if(!b)throw Error('Missing button');b.scrollIntoView({{block:'center'}});const r=b.getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}};");using var p=JsonDocument.Parse(value);await Mouse(p.RootElement.GetProperty("x").GetDouble(),p.RootElement.GetProperty("y").GetDouble());}
