    {
        await Eval($"const a=window.chitalka;let found=false;for(const section of a.engine.spine.spineItems){{await section.load(a.engine.load.bind(a.engine));if(section.document.body?.textContent.includes({Json.Encode(word)})){{await a.rendition.display(section.href);await new Promise(r=>setTimeout(r,180));const c=a.rendition.getContents()[0];const range=a.findTextRange(c.document,{{highlight:{Json.Encode(word)}}});if(range){{await a.rendition.display(c.cfiFromRange(range));found=true;break}}}}}}if(!found)throw Error('Word missing');await new Promise(r=>setTimeout(r,200));return true;");
        var value=await Eval($"const a=window.chitalka,c=a.rendition.getContents()[0],range=a.findTextRange(c.document,{{highlight:{Json.Encode(word)}}});const r=range.getBoundingClientRect(),f=c.document.defaultView.frameElement.getBoundingClientRect();return {{x:f.x+r.x+r.width/2,y:f.y+r.y+r.height/2}};");using var p=JsonDocument.Parse(value);await Mouse(p.RootElement.GetProperty("x").GetDouble(),p.RootElement.GetProperty("y").GetDouble(),2);
        await Check("native-selection-"+word,$"await new Promise(r=>setTimeout(r,250));if(!window.chitalka.selected?.text.includes({Json.Encode(word)}))throw Error('Native selection failed: '+window.chitalka.selected?.text);if(document.querySelector('#selectionCard').hidden)throw Error('Card hidden');if(document.querySelector('#translationArea').textContent.trim())throw Error('Automatic translation');return window.chitalka.selected.text;");
    }
    async Task NativeFileDialog(string path)
    {
        await Task.Run(async()=>{
            for(var n=0;n<120;n++) {
                nint dialog=0;EnumWindows((hwnd,_)=>{GetWindowThreadProcessId(hwnd,out var pid);if(pid==Environment.ProcessId){var name=new System.Text.StringBuilder(100);GetClassName(hwnd,name,100);if(name.ToString()=="#32770")dialog=hwnd;}return true;},0);
                if(dialog!=0) {
                    nint accept=0;EnumChildWindows(dialog,(hwnd,_)=>{var name=new System.Text.StringBuilder(100);GetClassName(hwnd,name,100);if(GetDlgCtrlID(hwnd)==1&&name.ToString()=="Button")accept=hwnd;return true;},0);
                    if(accept!=0){await Task.Delay(350);SendMessage(accept,0x00F5,0,0);return;}
                }
                await Task.Delay(100);
            }
            throw new InvalidOperationException("Native file dialog missing");
        });await Task.Delay(700);
    }
    async Task NativeYes(string title="Восстановление")
    {
        await Task.Run(async()=>{for(var n=0;n<250;n++){nint match=0;EnumWindows((hwnd,_)=>{GetWindowThreadProcessId(hwnd,out var pid);if(pid==Environment.ProcessId){var text=new System.Text.StringBuilder(512);GetWindowText(hwnd,text,512);if(text.ToString()==title)match=hwnd;}return true;},0);if(match!=0){SendMessage(match,0x0111,6,0);return;}await Task.Delay(100);}throw new InvalidOperationException("Confirmation missing: "+title);});await Task.Delay(300);
    }
    async Task FileAction(string code,string path) {window.QaDialogPath=path;var native=NativeFileDialog(path);await Eval(code);await native;window.QaDialogPath=null;}
